interface MorningNews extends IMarketNews {
  relTime: string;
  dayIndex: number;
  dateLabel: string;
  sourceLabel: string;
}

function buildMorningNews(baseNews: IMarketNews[], today: Date): MorningNews[] {
  const total = baseNews.length;
  const timePool = ['07:30', '08:00', '08:30', '09:00', '09:30', '10:00', '10:30', '11:00', '11:30', '14:00', '14:30', '15:00', '15:30', '16:00', '17:00'];
  const maxDays = 2;

  return baseNews.map((n, idx) => {
    const dayIndex = Math.min(maxDays, Math.floor((idx / Math.max(1, total)) * (maxDays + 1)));
    const timeIdx = (idx * 2 + 3) % timePool.length;
    const timeOfDay = timePool[(timePool.length - 1 - timeIdx + timePool.length) % timePool.length];
    const relTime = formatMorningTime(dayIndex, timeOfDay, today);
    // 稳定的日期标签：用 today 基于 dayIndex 计算，不随重渲染变化
    const targetDate = new Date(today);
    targetDate.setDate(today.getDate() - dayIndex);
    const month = targetDate.getMonth() + 1;
    const day = targetDate.getDate();
    const dateLabel = `${month}月${day}日 ${timeOfDay}`;
    // 来源标签：优先 publishTime 里的日期，否则用平台名+日期
    const sourceLabel = n.publishTime && n.publishTime.length > 0
      ? formatSourceFromPublishTime(n.publishTime)
      : `${n.platform} · ${month}月${day}日`;
    return { ...n, relTime, dayIndex, dateLabel, sourceLabel };
  }).sort((a, b) => a.dayIndex - b.dayIndex);
}

// 从 publishTime 字段解析出友好的来源+日期展示
// 支持格式："来源 · ISO时间" 或纯 ISO 时间 或 "YYYY-MM-DD HH:mm"
function formatSourceFromPublishTime(publishTime: string): string {
  if (!publishTime) return '市场早讯';
  // 如果包含 · 说明前面是来源名
  const sepIdx = publishTime.indexOf(' · ');
  let source = '';
  let timeStr = publishTime;
  if (sepIdx > 0) {
    source = publishTime.slice(0, sepIdx);
    timeStr = publishTime.slice(sepIdx + 3);
  }
  // 解析时间
  let date: Date | null = null;
  if (/^\d{4}-\d{2}-\d{2}T/.test(timeStr) || !isNaN(Date.parse(timeStr))) {
    const parsed = new Date(timeStr);
    if (!isNaN(parsed.getTime())) date = parsed;
  } else if (/^(\d{4})-(\d{2})-(\d{2})[ ](\d{2}):(\d{2})/.test(timeStr)) {
    const m = timeStr.match(/^(\d{4})-(\d{2})-(\d{2})[ ](\d{2}):(\d{2})/);
    if (m) date = new Date(parseInt(m[1]), parseInt(m[2]) - 1, parseInt(m[3]), parseInt(m[4]), parseInt(m[5]));
  }
  let dateLabel = '';
  if (date) {
    const month = date.getMonth() + 1;
    const day = date.getDate();
    const hour = date.getHours().toString().padStart(2, '0');
    const min = date.getMinutes().toString().padStart(2, '0');
    dateLabel = `${month}月${day}日 ${hour}:${min}`;
  }
  if (source && dateLabel) return `${source} · ${dateLabel}`;
  if (source) return source;
  if (dateLabel) return `市场早讯 · ${dateLabel}`;
  return '市场早讯';
}

// 将后端 news 适配成市场早讯格式
// 优先级：后端返回的 platform 字段 > 按 country/title 兜底映射 > 默认亚马逊
function adaptNewsToMarket(items: Array<{ id: string; platform?: string; country?: string; title: string; summary: string; source?: string }>): IMarketNews[] {
  // 国家 → 平台 的兜底映射（后端没返回 platform 字段时用）
  const countryToPlatform: Record<string, IMarketNews['platform']> = {
    '美国': '亚马逊',
    '日本': '亚马逊',
    '中国': '亚马逊',
    '英国': '亚马逊',
    '德国': '亚马逊',
    '法国': '亚马逊',
    '欧盟': '亚马逊',
    '欧美': '亚马逊',
    '韩国': '亚马逊',
    'TikTok': 'TikTok',
    '东南亚': 'TikTok',
    '泰国': 'TikTok',
    '越南': 'TikTok',
    '印尼': 'TikTok',
    '马来': 'TikTok',
    '马来西亚': 'TikTok',
    '菲律宾': 'TikTok',
  };
  // 标题关键词 → 平台 的兜底（country 也没有时按标题猜）
  const titlePlatformKeywords: Array<{ kw: string[]; platform: IMarketNews['platform'] }> = [
    { kw: ['亚马逊', 'FBA', 'Prime', 'AMZ', 'Listing'], platform: '亚马逊' },
    { kw: ['TikTok', '抖音国际版', '达人', '直播带货'], platform: 'TikTok' },
  ];
  const catKeywords = [
    { kw: ['政策', '新规', '规则', '审核', '入驻', '佣金', '关税', 'FBA', '配送费', '门槛'], cat: '政策' as const },
    { kw: ['销量', '增长', '搜索量', '销量', '旺季', '流量', '市场', '行情', '类目', '销量'], cat: '行情' as const },
    { kw: ['促销', 'Prime Day', '黑五', '网一', '购物节', '活动', '提报', '补贴', '招商'], cat: '活动' as const },
  ];

  return items.map((n, i) => {
    // 统一兜底：title/summary 缺省为空串，避免后续 includes 白屏
    const title = n.title || '';
    const summary = n.summary || '';
    // 1. 优先用后端直接返回的 platform 字段
    let platform: IMarketNews['platform'] = '亚马逊';
    if (n.platform && (n.platform === '亚马逊' || n.platform === 'TikTok')) {
      platform = n.platform;
    } else if (n.country && countryToPlatform[n.country]) {
      // 2. 按国家/地区兜底映射
      platform = countryToPlatform[n.country];
    } else {
      // 3. 再兜底：按标题关键词猜
      for (const pk of titlePlatformKeywords) {
        if (pk.kw.some(k => title.includes(k))) {
          platform = pk.platform;
          break;
        }
      }
    }

    let category: IMarketNews['category'] = '行情';
    for (const ck of catKeywords) {
      if (ck.kw.some(k => title.includes(k) || summary.includes(k))) {
        category = ck.cat;
        break;
      }
    }
    return {
      id: `api-${i}-${n.id}`,
      platform,
      title: n.title,
      category,
      summary: n.summary,
      publishTime: n.source ? `${n.source} · ${new Date().toISOString()}` : new Date().toISOString(),
    };
  });
}

// 两平台保底补位：确保亚马逊/TikTok每个平台至少有 N 条，不够就从 mock 池里按天轮换补上
function ensureAllPlatformsCovered(news: IMarketNews[], mockPool: IMarketNews[][], date: Date, minPerPlatform = 1): IMarketNews[] {
  const platforms: IMarketNews['platform'][] = ['亚马逊', 'TikTok'];
  const result = [...news];
  const dayOfYear = Math.floor((date.getTime() - new Date(date.getFullYear(), 0, 0).getTime()) / 86400000);

  // 把 mock 池里所有数据按平台分组（只保留亚马逊和 TikTok）
  const poolByPlatform: Record<string, IMarketNews[]> = { '亚马逊': [], 'TikTok': [] };
  mockPool.flat().forEach(n => {
    if (n.platform === '亚马逊' || n.platform === 'TikTok') {
      poolByPlatform[n.platform].push(n);
    }
  });

  platforms.forEach((p) => {
    const existing = result.filter(n => n.platform === p).length;
    const need = minPerPlatform - existing;
    if (need <= 0) return;

    const pool = poolByPlatform[p];
    if (pool.length === 0) return;

    // 按天轮换取，保证每天补的内容不一样
    const startIdx = dayOfYear % pool.length;
    for (let i = 0; i < need; i++) {
      const idx = (startIdx + i) % pool.length;
      result.push({ ...pool[idx], id: `fallback-${p}-${idx}` });
    }
  });

  return result;
}

const PLATFORMS = [
  { key: 'all', label: '全部', icon: TrendingUp },
  { key: '亚马逊', label: '亚马逊', icon: ShoppingBag },
  { key: 'TikTok', label: 'TikTok', icon: Megaphone },
] as const;

const typeColors: Record<IMarketNews['category'], string> = {
  '政策': 'bg-blue-100 text-blue-700',
  '行情': 'bg-green-100 text-green-700',
  '活动': 'bg-purple-100 text-purple-700',
};

const platformColors: Record<IMarketNews['platform'], string> = {
  '亚马逊': 'bg-orange-100 text-orange-700',
  'TikTok': 'bg-pink-100 text-pink-700',
};

export default function MarketMorningPage() {
  const { theme, festival } = useOutletContext<{ theme: ThemeConfig; festival: FestivalBadge }>();
  const [activePlatform, setActivePlatform] = useState<string>('all');
  const [windTab, setWindTab] = useState<'利好' | '严控' | '开店政策'>('利好');
  const [newsData, setNewsData] = useState<IMarketNews[]>([]);
  const [dataSource, setDataSource] = useState<'api' | 'mock'>('mock');
  const [loading, setLoading] = useState(true);
  const today = useMemo(() => new Date(), []);

  const [updateTime, setUpdateTime] = useState('');

  // 本地 mock 兜底数据（流量保底置顶 + 严打保底 + 日常池）
  const fallbackNews = useMemo<IMarketNews[]>(() => {
    const idx = getDailyIndex(MOCK_MARKET_NEWS_GROUPS.length, today);
    return [...TRAFFIC_FALLBACK_Q4, ...CRACKDOWN_FALLBACK, ...MOCK_MARKET_NEWS_GROUPS[idx]];
  }, [today]);

  // 加载新闻（优先 API，失败降级；force=true 强制刷新）
  const loadNews = async (showToast = false, force = false) => {
    try {
      const result = await fetchWithCache<any>('morning:global', '/morning', {
        ttl: DEFAULT_TTL,
        force,
      });
      if (result?.data?.items?.length > 0) {
        const adapted = adaptNewsToMarket(result.data.items);
        if (adapted.length > 0) {
          // 三平台保底补位，确保任一平台为0时从 mock 池补上（流量保底+严打保底始终置顶）
          const withFallback = ensureAllPlatformsCovered(
            [...TRAFFIC_FALLBACK_Q4, ...CRACKDOWN_FALLBACK, ...adapted],
            MOCK_MARKET_NEWS_GROUPS,
            today,
            1,
          );
          setNewsData(withFallback);
          setDataSource('api');
          setUpdateTime(formatCacheTime(result.timestamp));
          if (showToast) toast.success(force ? '早讯已刷新' : '早讯已更新');
          return;
        }
      }
    } catch (e) {
      logger.warn('[market-morning] news API failed, fallback:', String(e));
    }
    setNewsData(fallbackNews);
    setDataSource('mock');
    if (showToast) toast.info('已显示模拟数据');
  };

  useEffect(() => {
    let cancelled = false;
    // 先用 mock 立即渲染
    setNewsData(fallbackNews);
    loadNews().finally(() => {
      if (!cancelled) setLoading(false);
    });
    return () => { cancelled = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fallbackNews]);

  const dailyNews = useMemo<MorningNews[]>(() => {
    return buildMorningNews(newsData, today);
  }, [newsData, today]);

  // A/B/C 三类置顶排序：A站点流量→B开店政策→C严打管控
  // 匹配不到跳过，其余保持原序
  const applyTopPinOrder = (items: MorningNews[]): (MorningNews & { pinType?: 'A' | 'B' | 'C' })[] => {
    const kwA = ['流量', 'GMV', '增长', '峰值', '旺季', '销量', '同比', '飙升', '爆款', '榜单'];
    const kwB = ['入驻', '开店', '资质', '注册', '通道', '保证金', '招商', '新卖家'];
    const kwC = ['升级', '收紧', '罚款', '冻结', '停用', '严查', '禁止', '终止', 'KYC', '提高', '管控', '严打', '捆绑', '政策收紧', '合规'];

    const groupA: MorningNews[] = [];
    const groupB: MorningNews[] = [];
    const groupC: MorningNews[] = [];
    const rest: MorningNews[] = [];

    items.forEach(item => {
      const text = (item.title || '') + (item.summary || '');
      if (kwA.some(k => text.includes(k))) {
        groupA.push(item);
      } else if (kwB.some(k => text.includes(k))) {
        groupB.push(item);
      } else if (kwC.some(k => text.includes(k))) {
        groupC.push(item);
      } else {
        rest.push(item);
      }
    });

    const marked = (arr: MorningNews[], t: 'A' | 'B' | 'C') =>
      arr.map(x => ({ ...x, pinType: t }));

    return [...marked(groupA, 'A'), ...marked(groupB, 'B'), ...marked(groupC, 'C'), ...rest];
  };

  const filteredNews = useMemo(() => {
    const base = activePlatform === 'all' ? dailyNews : dailyNews.filter(n => n.platform === activePlatform);
    return applyTopPinOrder(base);
  }, [dailyNews, activePlatform]);

  // 从早讯里按关键词匹配出平台风向条目，匹配不足时用fallback补齐
  const platformWind = useMemo<Record<'利好' | '严控' | '开店政策', PlatformWindItem[]>>(() => {
    const keywords: Record<'利好' | '严控' | '开店政策', string[]> = {
      '利好': ['扶持', '补贴', '激励', '降低', '减免', '加速', '开放', '新卖家', '启航', '飞轮'],
      '严控': ['升级', '收紧', '罚款', '冻结', '停用', '严查', '禁止', '终止', 'KYC', '保证金上调', '提高'],
      '开店政策': ['入驻', '开店', '资质', '注册', '通道', '保证金', '入驻通道', '招商'],
    };

    const result: Record<'利好' | '严控' | '开店政策', PlatformWindItem[]> = {
      '利好': [],
      '严控': [],
      '开店政策': [],
    };

    // 尝试从实时/本地早讯里匹配
    const categories: Array<'利好' | '严控' | '开店政策'> = ['利好', '严控', '开店政策'];
    categories.forEach(cat => {
      const matched = newsData.filter(n =>
        keywords[cat].some(k => (n.title || '').includes(k) || (n.summary || '').includes(k))
      ).slice(0, 3).map(n => ({
        platform: n.platform,
        title: n.title,
        summary: n.summary,
        tag: '今日' as const,
      }));
      result[cat] = matched;

      // 不足3条时用fallback补齐
      if (result[cat].length < 3) {
        const fallbackPool = PLATFORM_WIND_FALLBACK[cat].filter(
          fb => !result[cat].some(m => m.platform === fb.platform)
        );
        const need = 3 - result[cat].length;
        result[cat] = [...result[cat], ...fallbackPool.slice(0, need)];
      }
    });

    return result;
  }, [newsData]);

  // 统计
  const stats = useMemo(() => {
    const byPlatform = { 亚马逊: 0, TikTok: 0 } as Record<string, number>;
    dailyNews.forEach(n => {
      if (n.platform === '亚马逊' || n.platform === 'TikTok') {
        byPlatform[n.platform]++;
      }
    });
    return byPlatform;
  }, [dailyNews]);

  function handleRefresh() {
    loadNews(true, true);
  }

  // ===== 折叠面板手风琴状态 =====
  const [expandedId, setExpandedId] = useState<string>('header');
  function toggleSection(id: string) {
    setExpandedId((prev) => (prev === id ? '' : id));
  }

  return (
    <div className="space-y-3">
      {/* Header */}
      <CollapsibleSection
        title="市场早讯"
        subtitle="MARKET BRIEFING · 今日平台动态"
        summary={`亚马逊 ${stats['亚马逊']} 条 · TikTok ${stats['TikTok']} 条`}
        badge={dataSource === 'api' ? '实时' : '模拟'}
        badgeColor={dataSource === 'api' ? 'success' : 'info'}
        theme={theme}
        expanded={expandedId === 'header'}
        onToggle={() => toggleSection('header')}
        icon={<TrendingUp className="size-5" />}
        className="!shadow-md"
        headerExtra={
          <button
            onClick={handleRefresh}
            className="text-xs px-2 py-1 rounded-full flex items-center gap-1 transition-colors"
            style={{
              backgroundColor: theme.primaryLight ? theme.primaryLight + '80' : 'hsl(226 100% 96%)',
              color: theme.primary,
            }}
          >
            <RefreshCw className={`size-3 ${loading ? 'animate-spin' : ''}`} />
            刷新
          </button>
        }
      >
        <div
          className="p-5 text-white rounded-xl"
          style={{
            background: `linear-gradient(135deg, ${theme.primary}, ${theme.primaryLight})`,
          }}
        >
          <div className="flex items-start gap-3 flex-1 min-w-0">
            <div className="size-10 rounded-xl bg-white/15 backdrop-blur flex items-center justify-center shrink-0">
              <TrendingUp className="size-5" />
            </div>
            <div className="space-y-1 min-w-0 flex-1">
              <div className="page-title-kicker opacity-80">MARKET BRIEFING</div>
              <div className="flex items-center gap-2 flex-wrap">
                <h1 className="page-title-main">市场早讯</h1>
                <span className={`text-[10px] px-1.5 py-0.5 rounded font-medium ${dataSource === 'api' ? 'bg-white/25' : 'bg-white/15'}`}>
                  {dataSource === 'api' ? '实时聚合' : '模拟数据'}
                </span>
              </div>
              <p className="page-title-sub flex items-center gap-1">
                <Calendar className="size-3" />
                今日早讯 · {getUpdateLabel(today)}
                {updateTime && dataSource === 'api' && (
                  <>
                    <span className="opacity-50">·</span>
                    <span>上次更新 {updateTime}</span>
                  </>
                )}
              </p>
            </div>
          </div>

          {/* 统计 */}
          <div className="grid grid-cols-2 gap-2 mt-4 pt-4 border-t border-white/15">
            {(['亚马逊', 'TikTok'] as const).map((p) => (
              <div key={p} className="bg-white/12 backdrop-blur rounded-lg py-2.5 px-2 text-center">
                <div className="text-xl font-bold tabular-nums leading-tight">{stats[p]}</div>
                <div className="text-[11px] opacity-80 mt-0.5">{p}动态</div>
              </div>
            ))}
          </div>
        </div>
      </CollapsibleSection>

       {/* 平台风向 */}
       <CollapsibleSection
        title="平台风向"
        subtitle="利好 / 严控 / 开店政策一览"
        summary="每日更新平台政策动态"
        badge="每日更新"
        badgeColor="warning"
        theme={theme}
        expanded={expandedId === 'wind'}
        onToggle={() => toggleSection('wind')}
        icon={<Compass className="size-5" />}
      >
        <Tabs defaultValue="利好" onValueChange={(v) => setWindTab(v as '利好' | '严控' | '开店政策')}>
          <TabsList className="w-full h-auto py-1 mb-3 grid grid-cols-3 bg-transparent">
            {(['利好', '严控', '开店政策'] as const).map(tab => (
              <TabsTrigger
                key={tab}
                value={tab}
                className="text-xs py-1.5 data-[state=active]:shadow-sm"
              >
                {tab === '利好' && '✅ '}{tab === '严控' && '⚠️ '}{tab === '开店政策' && '🏪 '}
                {tab}
              </TabsTrigger>
            ))}
          </TabsList>
          {(['利好', '严控', '开店政策'] as const).map(tab => (
            <TabsContent key={tab} value={tab} className="mt-0 space-y-2">
              {platformWind[tab].map((item, i) => (
                <div
                  key={`${tab}-${i}`}
                  className="p-3 rounded-lg"
                  style={{ backgroundColor: theme.ui.formulaCardBg }}
                >
                  <div className="flex items-start gap-2">
                    <Badge
                      className={`text-[10px] border-0 shrink-0 mt-0.5 ${platformColors[item.platform]}`}
                    >
                      {item.platform}
                    </Badge>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-1.5 flex-wrap">
                        <span className="text-sm font-medium text-foreground leading-snug">{item.title}</span>
                        <span className="text-[10px] px-1.5 py-0.5 rounded-full border" style={{ borderColor: theme.ui.cardBorder, color: theme.primary }}>
                          {item.tag}
                        </span>
                      </div>
                      <p className="text-xs text-muted-foreground mt-1 leading-relaxed">
                        {item.summary}
                      </p>
                    </div>
                  </div>
                </div>
              ))}
            </TabsContent>
          ))}
        </Tabs>
      </CollapsibleSection>

       {/* Platform Tabs */}
       <CollapsibleSection
        title="早讯列表"
        subtitle={`${filteredNews.length} 条 · 按平台筛选`}
        summary="亚马逊/TikTok 平台最新动态"
        badge={`${filteredNews.length} 条`}
        badgeColor="info"
        theme={theme}
        expanded={expandedId === 'list'}
        onToggle={() => toggleSection('list')}
        icon={<Zap className="size-5" />}
      >
       <Tabs defaultValue="all" onValueChange={setActivePlatform}>
         <TabsList className="w-full h-auto py-1 overflow-x-auto flex flex-nowrap">
           {PLATFORMS.map((p) => {
             const Icon = p.icon;
             return (
               <TabsTrigger key={p.key} value={p.key} className="text-xs py-1.5 shrink-0 flex items-center gap-1">
                 <Icon className="size-3.5" />
                 {p.label}
               </TabsTrigger>
             );
           })}
         </TabsList>

        <TabsContent value={activePlatform} className="mt-4 space-y-3">
          {loading ? (
            <div className="space-y-3">
              {[0, 1, 2, 3].map((i) => (
                <div key={i} className="rounded-xl p-4 animate-pulse" style={{ backgroundColor: theme.ui.glassBg, border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}` }}>
                  <div className="flex items-start justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2">
                      <div className="w-5 h-5 rounded-full bg-muted" />
                      <div className="h-4 w-24 bg-muted rounded" />
                    </div>
                    <div className="h-3 w-16 bg-muted rounded" />
                  </div>
                  <div className="h-4 bg-muted rounded w-4/5 mb-2" />
                  <div className="h-3 bg-muted rounded w-3/4 mb-2" />
                  <div className="h-3 bg-muted rounded w-1/2" />
                </div>
              ))}
            </div>
          ) : filteredNews.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground text-sm">
              暂无新闻
            </div>
          ) : (
            filteredNews.map((news, idx) => (
              <Card
                key={news.id}
                className="border-0 hover:shadow-md transition-shadow overflow-hidden"
                style={{
                  backgroundColor: theme.ui.glassBg,
                  backdropFilter: 'blur(10px) saturate(180%)',
                  WebkitBackdropFilter: 'blur(10px) saturate(180%)',
                  boxShadow: theme.ui.glassShadow,
                  border: `1px solid ${theme.ui.glassBorder || theme.ui.cardBorder}`,
                }}
              >
                <div className="h-1" style={{ backgroundColor: theme.primary }} />
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between gap-2">
                    <CardTitle className="text-sm font-semibold leading-snug flex-1 text-primary-strong">
                      <span
                        className="inline-flex items-center justify-center size-5 rounded-full text-[10px] font-bold text-white shrink-0 mr-2 -mt-0.5"
                        style={{ backgroundColor: theme.primary }}
                      >
                        {idx + 1}
                      </span>
                      {news.title}
                    </CardTitle>
                    <span className="text-[11px] text-tertiary-strong shrink-0 whitespace-nowrap pt-0.5 tabular-nums">
                      {news.relTime}
                    </span>
                  </div>
                  <div className="flex items-center gap-1.5 flex-wrap mt-1">
                    {news.pinType === 'A' && (
                      <Badge
                        className="text-[11px] border-0 font-medium"
                        style={{
                          backgroundColor: `${theme.primary}14`,
                          color: theme.primary,
                        }}
                      >
                        🔥 流量
                      </Badge>
                    )}
                    {news.pinType === 'B' && (
                      <Badge
                        className="text-[11px] border-0"
                        style={{
                          backgroundColor: `${theme.priority.p1}14`,
                          color: theme.priority.p1,
                        }}
                      >
                        开店
                      </Badge>
                    )}
                    {news.pinType === 'C' && (
                      <Badge
                        className="text-[11px] border-0"
                        style={{
                          backgroundColor: `${theme.priority.p0}12`,
                          color: theme.priority.p0,
                        }}
                      >
                        管控
                      </Badge>
                    )}
                    <Badge className={`text-[11px] ${platformColors[news.platform]} border-0`}>
                      {news.platform}
                    </Badge>
                    <Badge className={`text-[11px] ${typeColors[news.category]} border-0`}>
                      {news.category}
                    </Badge>
                  </div>
                </CardHeader>
                <CardContent className="pt-0">
                  <div className="flex items-center justify-between gap-2 mb-1.5">
                    <span className="text-[11px] text-muted-foreground truncate">
                      📰 {news.sourceLabel}
                    </span>
                    <span className="text-[11px] text-tertiary-strong shrink-0 whitespace-nowrap tabular-nums">
                      {news.dateLabel}
                    </span>
                  </div>
                  <p className="text-sm text-secondary-strong leading-relaxed">
                    {news.summary}
                  </p>
                </CardContent>
              </Card>
            ))
          )}
        </TabsContent>
       </Tabs>
      </CollapsibleSection>
    </div>
  );
}
